INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.58.0',
  '2026-07-30',
  'AI — задача больше не зависает в «выполняется», если агент перезапустили',
  E'Исправлено: если агента на машине перезапустили или он упал во время задачи, задача навсегда оставалась в статусе «выполняется». Теперь такой прогон сразу помечается ошибкой «прогон прерван», и приходит уведомление в бот — видно, что нужно перезапустить. Работает в обе стороны: агент при остановке успевает сообщить о прерванных задачах, а если он умер жёстко (питание, kill) — сервер закрывает брошенные прогоны при следующем подключении агента. Живые задачи при этом не трогаются: обрыв сети или перезапуск сервера их не прерывает.',
  E'Причина инцидента: AI-задача v2.57.0 сама обновляла habits-ai-agent и делала systemctl --user restart — systemd убил cgroup вместе с дочерним процессом claude, результат уже некому было отправить (run 7 висел в running; реапер закрыл бы только через 2ч и лишь при листинге). Фикс двусторонний. Агент v1.6.0: hello теперь несёт active[] (принятые этим процессом прогоны) и обработчик SIGTERM/SIGINT — перед выходом шлёт run_result «прогон прерван: агент остановлен» по всем inflight (принятые без готового результата), затем 500мс на отправку. Сервер: FailOrphanedAIRuns(machine_id, active[]) — UPDATE ... FROM ai_tasks закрывает running-прогоны машины, которых нет в active, RETURNING id; вызывается в agentWS сразу после hello, до Serve/deliverQueued; по каждому закрытому идёт notifyRunFinished (уведомление владельцу). Защита от ложных срабатываний: прогон с результатом на доставке остаётся в accepted → попадает в active → не закрывается (его дошлёт flusher). E2E: (1) симулированный зависший running закрылся при подключении агента + уведомление; (2) живой прогон пережил рестарт сервера (hello active=1, статус running); (3) SIGTERM агенту посреди прогона — статус error за ~1с с текстом про остановку агента.'
);
